<script setup lang="ts">
import {ref,onMounted} from 'vue';import {getGitActivity} from './gitActivity';
const data=ref<any>(null),busy=ref(false),error=ref('');async function load(){busy.value=true;error.value='';try{data.value=await getGitActivity();}catch(e){error.value=e.message;}finally{busy.value=false;}}onMounted(load);
</script>
<template><section class="git-card"><header><div><span class="studio-eyebrow">SMALL STEPS, EVERY DAY</span><h2>代码留下的足迹 <small v-if="data?.username">{{data.provider}} / {{data.username}}</small></h2></div><el-button size="small" :loading="busy" @click="load">刷新</el-button></header><p v-if="busy&&!data">正在连接代码星球…</p><p v-if="error||data?.error" role="status">{{error||data.error}}{{data?.stale?' · 正在展示上一次缓存':''}}</p><template v-if="data?.days?.length"><div class="git-scroll"><div class="git-days" aria-label="公开 Git 动态日历"><span v-for="day in data.days" :key="day.date" :class="'level-'+Math.min(4,day.count)" :title="day.date+' · '+day.count+' 条公开动态'" tabindex="0" :aria-label="day.date+'，'+day.count+' 条公开动态'"/></div></div><footer><b>{{data.total}} 条可见动态</b><span>少 <i/> <i/> <i/> <i/> 多</span><a :href="data.profileUrl" target="_blank" rel="noopener noreferrer">前往主页 ↗</a></footer></template><p class="git-caption">{{data?.message}}</p><RouterLink v-if="data&&!data.configured" to="/profile">设置我的 Git 账号 →</RouterLink></section></template>
<style scoped>.git-card{padding:26px;border:1px solid var(--studio-line);background:var(--studio-panel);border-radius:18px;margin:24px 0}.git-card header,.git-card footer{display:flex;justify-content:space-between;gap:15px;align-items:center}.git-card h2{font-size:19px;margin:10px 0 20px}.git-card h2 small{font-size:11px;font-weight:400;display:block;margin-top:8px;color:var(--studio-muted)}.git-scroll{overflow:auto;padding:8px 0 16px}.git-days{display:grid;grid-auto-flow:column;grid-template-rows:repeat(7,11px);grid-auto-columns:11px;gap:4px;width:max-content}.git-days span{background:#edf0ed;border-radius:3px;transition:transform .15s}.git-days span:focus,.git-days span:hover{outline:2px solid #738b7d;transform:scale(1.3)}.git-days .level-1{background:#c1d8b7}.git-days .level-2{background:#93bca4}.git-days .level-3{background:#588b73}.git-days .level-4{background:#326450}.git-caption{font-size:11px;line-height:1.8;color:var(--studio-muted);margin-top:18px}.git-card footer{font-size:11px;flex-wrap:wrap}.git-card footer span{display:flex;gap:4px;align-items:center}.git-card i{height:10px;width:10px;background:#c1d8b7;border-radius:2px}.git-card i:nth-child(2){background:#93bca4}.git-card i:nth-child(3){background:#588b73}.git-card i:nth-child(4){background:#326450}</style>
